  "sz.carsBody": { pl: "Lamborghini Huracán Super Trofeo oraz Porsche 911 GT3 Cup to samochody stworzone tylko i wyłącznie do jazdy torowej, nie posiadające homologacji oraz bardzo surowe i trudne w prowadzeniu.", en: "The Lamborghini Huracán Super Trofeo and the Porsche 911 GT3 Cup are cars built solely and exclusively for track driving — with no road homologation, and very raw and demanding to drive.", kind: "html" },
  "sz.car1name": { pl: "LAMBORGHINI HURACÁN", en: "LAMBORGHINI HURACÁN", kind: "text" },
  "sz.car1sub": { pl: "SUPER TROFEO", en: "SUPER TROFEO", kind: "text" },
  "sz.car2name": { pl: "PORSCHE 911", en: "PORSCHE 911", kind: "text" },
  "sz.car2sub": { pl: "GT3 CUP", en: "GT3 CUP", kind: "text" },
  "sz.tag1": { pl: "BEZ HOMOLOGACJI", en: "NO HOMOLOGATION", kind: "text" },
  "sz.tag2": { pl: "TYLKO TOR", en: "TRACK ONLY", kind: "text" },
  "sz.tag3": { pl: "SUROWE W PROWADZENIU", en: "RAW TO DRIVE", kind: "text" },

  // McRae quote
  "sz.quotePre": { pl: "Straight roads are for", en: "Straight roads are for", kind: "text" },
  "sz.quoteRed1": { pl: "fast cars", en: "fast cars", kind: "text" },
  "sz.quoteMid": { pl: ", turns are for", en: ", turns are for", kind: "text" },
  "sz.quoteRed2": { pl: "fast drivers", en: "fast drivers", kind: "text" },
  "sz.quoteAuthor": { pl: "COLIN McRAE", en: "COLIN McRAE", kind: "text" },

  // stages / ścieżka rozwoju
  "sz.stagesEyebrow": { pl: "ŚCIEŻKA ROZWOJU", en: "YOUR PROGRESSION", kind: "text" },
  "sz.stagesTitle": { pl: "OD PODSTAW DO PODIUM", en: "FROM THE BASICS TO THE PODIUM", kind: "text" },
  "sz.stagesHint": { pl: "WYBIERZ BIEG", en: "SELECT A GEAR", kind: "text" },
  "sz.s1name": { pl: "STAGE 1", en: "STAGE 1", kind: "text" },
  "sz.s1tag": { pl: "OD PODSTAW", en: "FROM THE BASICS", kind: "text" },
  "sz.s1desc": { pl: "Pierwszy kontakt z torem. Poznajesz podstawy techniki jazdy sportowej, tor wyścigowy i pracę za kierownicą prawdziwej wyścigówki — bezpiecznie i pod okiem instruktora-zawodnika.", en: "Your first contact with the track. You learn the basics of sport driving technique, the racing circuit and working behind the wheel of a real race car — safely, guided by a competitor-instructor.", kind: "html" },
  "sz.s2name": { pl: "STAGE 2", en: "STAGE 2", kind: "text" },
  "sz.s2tag": { pl: "DLA ŚREDNIO-ZAAWANSOWANYCH", en: "FOR THE INTERMEDIATE", kind: "text" },
  "sz.s2desc": { pl: "Rozwijasz płynność i szybkość. Trail braking, dobór idealnego toru jazdy i praca z przyczepnością na wyższym poziomie — zaczynasz naprawdę atakować zakręty.", en: "You develop smoothness and speed. Trail braking, choosing the ideal racing line and working with grip at a higher level — you start to really attack the corners.", kind: "html" },
  "sz.s3name": { pl: "STAGE 3", en: "STAGE 3", kind: "text" },
  "sz.s3tag": { pl: "DLA ZAWODNIKÓW", en: "FOR COMPETITORS", kind: "text" },
  "sz.s3desc": { pl: "Poziom wyścigowy. Ściganie się koło w koło, starty, walka o setne sekundy i przygotowanie do startów w prawdziwych zawodach za kierownicą Porsche GT3 Cup i Lamborghini Super Trofeo.", en: "Racing level. Wheel-to-wheel battles, race starts, fighting for hundredths of a second and preparing for real competition behind the wheel of the Porsche GT3 Cup and Lamborghini Super Trofeo.", kind: "html" },
  "sz.s4name": { pl: "ICE", en: "ICE", kind: "text" },
  "sz.s4tag": { pl: "DRIVING EXPERIENCE", en: "DRIVING EXPERIENCE", kind: "text" },
  "sz.s4desc": { pl: "Pełna kontrola pojazdu na lodzie i śniegu. Kontrolowany poślizg, precyzja i pewność w najtrudniejszych warunkach — szkoła, która procentuje na każdej nawierzchni.", en: "Full vehicle control on ice and snow. Controlled drift, precision and confidence in the toughest conditions — a school that pays off on every surface.", kind: "html" },
  "sz.stagesCta": { pl: "ZOBACZ OFERTĘ", en: "SEE THE OFFER", kind: "text" },

  // closing band
  "sz.bandEyebrow": { pl: "DROGA OTWARTA", en: "THE ROAD IS OPEN", kind: "text" },
  "sz.bandTitle": { pl: "SZEROKO OTWARTA DROGA", en: "A WIDE-OPEN ROAD", kind: "text" },
  "sz.bandBody": { pl: "Dzięki szkole droga do rozwoju umiejętności sport driving lub rozpoczęcia ścigania się na wyższym poziomie jest już teraz szeroko otwarta.", en: "Thanks to the school, the path to developing your sport-driving skills — or to start racing at a higher level — is now wide open.", kind: "html" },
  "sz.bandPhoto": { pl: "/assets/szkola/onas2.webp", en: null, kind: "image" },

  // CTA
  "sz.ctaEyebrow": { pl: "SPORT DRIVING EXPERIENCE", en: "SPORT DRIVING EXPERIENCE", kind: "text" },
  "sz.ctaTitle": { pl: "ZACHĘCAMY DO KONTAKTU", en: "GET IN TOUCH WITH US", kind: "text" },
  "sz.ctaSub": { pl: "Skontaktuj się z nami, aby omówić szczegóły szkolenia i dobrać program idealny dla Ciebie.", en: "Contact us to discuss the details of the training and choose the program that's perfect for you.", kind: "text" },
