  // --- founder block (home, before the instructors) ---
  "founder.eyebrow": { pl: "ZAŁOŻYCIEL FASTLINE RACING ACADEMY", en: "FOUNDER OF FASTLINE RACING ACADEMY", kind: "text" },
  "founder.title": { pl: "MARIUSZ MIĘKOŚ", en: "MARIUSZ MIĘKOŚ", kind: "text" },
  "founder.role": { pl: "9-KROTNY WYŚCIGOWY MISTRZ POLSKI · TWÓRCA I SZEF SZKOŁY", en: "9-TIME POLISH RACING CHAMPION · FOUNDER AND HEAD OF THE SCHOOL", kind: "text" },
  "founder.body": { pl: "Założyciel Fastline Racing Academy — dzięki sukcesom za kierownicą wyścigówek stara się wykorzystać doświadczenie z torów i rozwijać programy treningowe jazdy sportowej i wyścigowej. Mistrz Polski w wyścigach samochodowych WSMP 2020, 2019, 2018 i 2017, wicemistrz Europy. Pięciokrotny uczestnik 24-godzinnego wyścigu w Dubaju. Instruktor Porsche Driving Experience 2017. Obecnie ściga się Lamborghini Huracán Super Trofeo.", en: "Founder of Fastline Racing Academy — building on his success behind the wheel of race cars, he brings track experience into sport and racing driving programmes. Polish champion in the WSMP series in 2020, 2019, 2018 and 2017, European vice-champion. Five-time entrant of the Dubai 24 Hours. Porsche Driving Experience instructor in 2017. Currently racing a Lamborghini Huracán Super Trofeo.", kind: "html" },
  "founder.quote": { pl: "Na torze nie ma miejsca na przypadek. Jest technika, głowa i tysiące okrążeń.", en: "There is no room for chance on the track. There is technique, a cool head and thousands of laps.", kind: "text" },
