  "card.net": { pl: "netto", en: "net", kind: "text" },
  "card.includes": { pl: "W CENIE", en: "INCLUDED", kind: "text" },
  "card.descTitle": { pl: "OPIS SZKOLENIA", en: "TRAINING DESCRIPTION", kind: "text" },
  "card.theory": { pl: "SZKOLENIE TEORETYCZNE", en: "THEORY SESSION", kind: "text" },
  "card.practice": { pl: "SZKOLENIE PRAKTYCZNE", en: "PRACTICAL TRAINING", kind: "text" },
  "card.cert": { pl: "CERTYFIKAT UKOŃCZENIA SZKOLENIA", en: "TRAINING CERTIFICATE", kind: "text" },
  "card.certBody": { pl: "Każdy uczestnik szkolenia otrzyma Certyfikat Szkolenia Fastline Racing Academy, podpisany własnoręcznie przez wielokrotnego wyścigowego Mistrza Polski Mariusza Miękosia.", en: "Every participant receives a Fastline Racing Academy training certificate, personally signed by the multiple Polish racing champion Mariusz Miękoś.", kind: "html" },
  "card.instr": { pl: "NASI INSTRUKTORZY TO UTYTUŁOWANI ZAWODNICY", en: "OUR INSTRUCTORS ARE DECORATED COMPETITORS", kind: "text" },
  "card.instrBody": { pl: "Kadra Fastline Racing Academy to doświadczeni instruktorzy, z których każdy jest aktualnie uprawiającym motorsport czynnym zawodnikiem — reprezentanci wyścigów, rajdów, driftu, rallycrossu i sim-racingu.", en: "The Fastline Racing Academy team are experienced instructors, each an active motorsport competitor — from circuit racing, rallying, drifting, rallycross and sim-racing.", kind: "html" },
  "card.lead": { pl: "Szkolenia jazdy sportowej na torze wyścigowym z instruktorem 1 na 1! Poznaj tajniki szybkiego pokonywania zakrętów, linii wyścigowej, apexów, balansu samochodu, pracy na pedałach, pracy opon i wiele więcej!", en: "Sport driving training on a race track with a 1-on-1 instructor! Learn the secrets of fast cornering, the racing line, apexes, car balance, pedal work, tyre behaviour and much more!", kind: "html" },
  "card.theoryBody": { pl: "Godzinny wykład o podstawach wyścigowej jazdy po torze, prowadzony przez naszych instruktorów — czynnych zawodników motorsportu. Dowiesz się o poprawnej pozycji za kierownicą i ułożeniu nóg na pedałach, geometrii zakrętu, idealnych punktach hamowania i momentach przyspieszania, poprawnej linii wyścigowej, niebezpiecznych zakrętach i apexach.", en: "A one-hour lecture on the basics of racing on a circuit, run by our instructors — active motorsport competitors. Seating position and pedal work, corner geometry, ideal braking points and acceleration moments, the correct racing line, dangerous corners and apexes.", kind: "html" },
  "card.practiceBody": { pl: "Jazda samochodem sportowym po torze w formule 1:1 — instruktor zawsze siedzi obok, skupiając całą uwagę na Tobie. Zaczynamy pokazowym okrążeniem instruktora, potem siadasz za kierownicą. Trenujesz jazdę prawidłową linią, jazdę na limicie samochodu, zarządzanie dynamiczną masą, „opieranie się na oponie”, wychodzenie z zakrętów i analizę geometrii zakrętów.", en: "Driving a sports car on the track 1:1 — the instructor always sits next to you with full attention on you. We start with a demo lap by the instructor, then you take the wheel. You train the correct line, driving at the limit, managing dynamic weight, leaning on the tyre, corner exits and corner geometry.", kind: "html" },
  "card.iceLead": { pl: "Fastline Ice Driving Experience to profesjonalny program treningów jazdy sportowej po torach lodowych Finlandii — samochodami sportowymi na oponach z kolcami, pod opieką zawodników sportów samochodowych, na kilku torach lodowych o różnej konfiguracji w Laponii.", en: "Fastline Ice Driving Experience is a professional programme of sport-driving training on the frozen lakes of Finland — in sports cars on studded tyres, with racing drivers as coaches, on several ice tracks of different layouts in Lapland.", kind: "html" },
  "card.iceList": { pl: "Zaawansowane umiejętności jazdy po lodzie w samochodach wyścigowych i rajdowych\nProwadzenie na sportowych oponach z kolcami i sterowanie pojazdem z dużą prędkością na lodzie\nNajszybszy tor jazdy i prawidłowa technika jazdy poślizgami\nZarządzanie balansem samochodu i skręcanie techniką skandynawskiego flicku\nTechniki jazdy autami z napędem na przód, tył i 4×4\nWybrane treningi z pomiarem czasu i analizą telemetryczną", en: "Advanced ice-driving skills in race and rally cars\nDriving on studded sport tyres and controlling the car at speed on ice\nThe fastest line and correct drifting technique\nManaging car balance and the Scandinavian flick\nFront-, rear- and all-wheel-drive techniques\nSelected sessions with timing and telemetry analysis", kind: "html" },
  "card.iceNote": { pl: "Warunkiem rezerwacji jest wpłata 100% ceny wg bankowego kursu sprzedaży euro. Istnieje możliwość zamiany lub dokupienia sesji w Porsche 911 Carrera 4 GTS.", en: "Booking requires a 100% payment at the bank's euro selling rate. Sessions in the Porsche 911 Carrera 4 GTS can be swapped or added.", kind: "html" },
  "card.pln": { pl: "do zapłaty w PLN", en: "payable in PLN", kind: "text" },

