  "fir.eyebrow": { pl: "FASTLINE RACING ACADEMY — EVENTY FIRMOWE", en: "FASTLINE RACING ACADEMY — CORPORATE EVENTS", kind: "text" },
  "fir.title": { pl: "TWÓJ EVENT NA TORZE WYŚCIGOWYM", en: "YOUR EVENT ON A RACE TRACK", kind: "text" },
  "fir.sub": { pl: "Adrenalina, sportowe supersamochody i profesjonalne szkolenie jazdy prowadzone przez najbardziej utytułowanych kierowców w Polsce. Kompleksowa organizacja imprez firmowych, integracji i wydarzeń B2B — na najlepszych torach w Polsce i Europie.", en: "Adrenaline, sports supercars and professional driving training run by Poland's most decorated racing drivers. Full-service corporate events, team building and B2B days — on the best circuits in Poland and Europe.", kind: "html" },
  "fir.ctaConfig": { pl: "SKONFIGURUJ SWÓJ EVENT", en: "CONFIGURE YOUR EVENT", kind: "text" },
  "fir.ctaTalk": { pl: "POROZMAWIAJMY", en: "LET'S TALK", kind: "text" },
  "fir.h1a": { pl: "Tor Łódź · Tor Modlin", en: "Łódź · Modlin circuits", kind: "text" },
  "fir.h1b": { pl: "oraz tory w Polsce i Europie", en: "plus circuits across Poland and Europe", kind: "text" },
  "fir.h2a": { pl: "15–200+ uczestników", en: "15–200+ participants", kind: "text" },
  "fir.h2b": { pl: "elastyczna skala wydarzenia", en: "flexible event scale", kind: "text" },
  "fir.h3a": { pl: "Pełne zaplecze i obsługa", en: "Full facilities and crew", kind: "text" },
  "fir.h3b": { pl: "od koncepcji po realizację", en: "from concept to delivery", kind: "text" },
  "fir.aboutEyebrow": { pl: "O EVENCIE", en: "ABOUT THE EVENT", kind: "text" },
  "fir.aboutTitle": { pl: "SPOTKANIE NA TORZE, KTÓRE ZAPAMIĘTAJĄ NA DŁUGO", en: "A DAY ON THE TRACK THEY WILL REMEMBER FOR YEARS", kind: "text" },
  "fir.about1": { pl: "Event ma formę spotkania na torze, którego główną aktywnością jest szkolenie jazdy bezpiecznej i sportowej z instruktorami–zawodnikami, za kierownicą floty supersamochodów Fastline Racing Academy.", en: "The event is a track day built around safe and sport driving training with competitor-instructors, behind the wheel of the Fastline Racing Academy supercar fleet.", kind: "html" },
  "fir.about2": { pl: "Wydarzenie może kłaść nacisk na silne emocje, rywalizację i szybką jazdę, ale też na przekazanie profesjonalnej wiedzy o technikach prowadzenia auta. Niezależnie od scenariusza, czas na torze to niezapomniane wspomnienie i doskonała platforma do rozmów biznesowych — w oprawie hospitality wzorowanej na motorhome Formuły 1.", en: "The day can focus on emotion, competition and speed, or on professional car-control know-how. Whatever the scenario, time on the track is an unforgettable memory and a great platform for business conversations — with hospitality modelled on a Formula 1 motorhome.", kind: "html" },
  "fir.b2bT": { pl: "PARTNERZY BIZNESOWI", en: "BUSINESS PARTNERS", kind: "text" },
  "fir.b2bB": { pl: "Budowanie lojalności i relacji z klientami — unikalne przeżycie, które wyróżnia Twoją markę i otwiera rozmowy.", en: "Loyalty and relationships with clients — a unique experience that sets your brand apart and opens conversations.", kind: "html" },
  "fir.hrT": { pl: "PRACOWNICY", en: "EMPLOYEES", kind: "text" },
  "fir.hrB": { pl: "Integracja, motywacja i team building w emocjach, których nie da żadne standardowe wyjście firmowe.", en: "Integration, motivation and team building with emotions no standard company outing can match.", kind: "html" },
  "fir.st1v": { pl: "45134", en: "45134", kind: "text" }, "fir.st1l": { pl: "KM NA TORZE", en: "KM ON TRACK", kind: "text" },
  "fir.st2v": { pl: "4230", en: "4230", kind: "text" }, "fir.st2l": { pl: "KONI MECHANICZNYCH W STAJNI", en: "HORSEPOWER IN THE STABLE", kind: "text" },
  "fir.st3v": { pl: "1300", en: "1300", kind: "text" }, "fir.st3l": { pl: "PRZESZKOLONYCH KIEROWCÓW", en: "DRIVERS TRAINED", kind: "text" },
